"""A least-recently-used cache with optional time-to-live (TTL) expiry."""
import time
from collections import OrderedDict


class _UseDefault:
    """Sentinel type: 'use the cache's default ttl'."""

    def __repr__(self):
        return "USE_DEFAULT"


USE_DEFAULT = _UseDefault()


def _check_ttl(ttl):
    if ttl is not None and not ttl > 0:
        raise ValueError("ttl must be None or greater than 0")
    return ttl


class _Entry:
    __slots__ = ("value", "stored_at", "ttl")

    def __init__(self, value, stored_at, ttl):
        self.value = value
        self.stored_at = stored_at
        self.ttl = ttl


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self._default_ttl = _check_ttl(ttl)
        self._clock = clock
        self._items = OrderedDict()

    @staticmethod
    def _is_live(entry, now):
        # Expired as soon as now - stored_at >= ttl.
        return entry.ttl is None or now - entry.stored_at < entry.ttl

    def _live_entry(self, key, now):
        """Return the entry for key if present and live, else None."""
        entry = self._items.get(key)
        if entry is None or not self._is_live(entry, now):
            return None
        return entry

    def get(self, key, default=None):
        """Return the value and mark the entry as most recently used."""
        entry = self._live_entry(key, self._clock())
        if entry is None:
            return default
        self._items.move_to_end(key)
        return entry.value

    def peek(self, key, default=None):
        """Return the value without touching the order."""
        entry = self._live_entry(key, self._clock())
        return default if entry is None else entry.value

    def put(self, key, value, ttl=USE_DEFAULT):
        if ttl is USE_DEFAULT:
            ttl = self._default_ttl
        else:
            _check_ttl(ttl)
        now = self._clock()
        entry = _Entry(value, now, ttl)

        if self._live_entry(key, now) is not None:
            # Replace in place: restart lifetime, become most recently used.
            self._items[key] = entry
            self._items.move_to_end(key)
            return

        # New key (or an expired entry under this key, which counts as absent).
        self._items.pop(key, None)
        if len(self._items) >= self.capacity:
            self._purge_expired(now)
        if len(self._items) >= self.capacity:
            self._items.popitem(last=False)  # evict least recently used live entry
        self._items[key] = entry

    def _purge_expired(self, now):
        dead = [k for k, e in self._items.items() if not self._is_live(e, now)]
        for k in dead:
            del self._items[k]

    def keys(self):
        """Live keys from least to most recently used."""
        now = self._clock()
        return [k for k, e in self._items.items() if self._is_live(e, now)]

    def __contains__(self, key):
        return self._live_entry(key, self._clock()) is not None

    def __len__(self):
        now = self._clock()
        return sum(1 for e in self._items.values() if self._is_live(e, now))
